{
  "omision_contenido_tecnologico": {
    "definicion": "Consiste en la exclusión deliberada de información relacionada con avances, productos o implicaciones de la tecnología en una noticia o informe, de modo que el público no perciba la relevancia o el impacto de dichos elementos. Se emplea para simplificar el mensaje, evitar controversias o mantener una narrativa que favorezca intereses particulares.",
    "ejemplo": "En octubre de 2026, varios medios internacionales cubrieron el lanzamiento del nuevo procesador de IA de Nvidia sin mencionar las críticas de expertos sobre el consumo energético y los riesgos de sesgo algorítmico.",
    "como_detectarla": [
      "1. Comparar el contenido publicado con comunicados de prensa o informes técnicos que incluyan detalles tecnológicos.",
      "2. Buscar menciones de términos clave (IA, algoritmo, seguridad, privacidad) que estén ausentes pero que sean relevantes para el tema tratado.",
      "3. Analizar fuentes alternas o expertas para identificar información tecnológica omitida en la pieza original."
    ]
  },
  "omision_deliberada_IA": {
    "definicion": "Es la exclusión intencional de cualquier referencia a la inteligencia artificial cuando ésta juega un papel central en la historia o el producto descrito. Busca minimizar la percepción de que la IA influye en decisiones, procesos o resultados, a menudo para evitar temores o regulaciones.",
    "ejemplo": "En julio de 2026, un anuncio de una cadena de supermercados sobre la automatización de su logística omitió señalar que el sistema de gestión de inventario está basado en un algoritmo de IA que decide precios dinámicos.",
    "como_detectarla": [
      "1. Identificar la tecnología subyacente del producto o servicio mediante documentos técnicos o patentes.",
      "2. Revisar entrevistas y declaraciones de la empresa donde se mencione IA y comparar con la cobertura mediática.",
      "3. Detectar la ausencia de palabras clave como \"IA\", \"machine learning\" o \"algoritmo\" en artículos que traten sobre procesos automatizados."
    ]
  },
  "framing_noticias_locales_culturales": {
    "definicion": "Técnica que presenta eventos locales o culturales bajo una perspectiva que resalta ciertos valores, tradiciones o conflictos, orientando la interpretación del público. El encuadre selecciona qué aspectos destacar y cuáles minimizar para moldear la opinión pública.",
    "ejemplo": "En agosto de 2026, la prensa regional de Andalucía cubrió la Feria de Abril enfocándose en la \"pérdida de tradiciones\" frente a la creciente presencia de stands de marcas internacionales, creando una narrativa de resistencia cultural.",
    "como_detectarla": [
      "1. Analizar qué elementos (historia, economía, identidad) se enfatizan y cuáles quedan fuera del relato.",
      "2. Comparar la cobertura con otras fuentes que ofrezcan una visión más equilibrada del mismo evento.",
      "3. Identificar el uso de adjetivos y metáforas que guían la valoración del lector (p. ej., \"auténtico\", \"amenazado\")."
    ]
  },
  "enfoque_selectivo_controversias_politicas": {
    "definicion": "Consiste en destacar únicamente los aspectos de una disputa política que favorecen una posición o actor, mientras se silencian los argumentos contrarios o contextos relevantes, con el fin de influir en la percepción del público.",
    "ejemplo": "En junio de 2026, varios portales de noticias españoles resaltaron los comentarios del líder del PP sobre la reforma laboral, omitiendo las críticas del PSOE y de sindicatos que defendían la medida como necesaria para la recuperación económica.",
    "como_detectarla": [
      "1. Listar los principales argumentos y actores involucrados en la controversia.",
      "2. Verificar qué de esos puntos aparecen o desaparecen en la cobertura mediática analizada.",
      "3. Evaluar la proporción de espacio y tono dedicado a cada posición para identificar sesgos de selección."
    ]
  },
  "omision_tema_relevante": {
    "definicion": "Práctica de excluir deliberadamente un asunto de importancia pública o social dentro de una noticia, informe o discurso, con el objetivo de desviar la atención, minimizar la crítica o proteger intereses específicos.",
    "ejemplo": "En septiembre de 2026, un reportaje sobre la reforma educativa en México omitió mencionar los recortes presupuestarios a programas de inclusión de estudiantes con discapacidades, a pesar de que el tema había sido central en el debate legislativo.",
    "como_detectarla": [
      "1. Revisar agendas, documentos oficiales o debates parlamentarios para identificar temas citados oficialmente.",
      "2. Contrastar esos temas con el contenido publicado y detectar ausencias notables.",
      "3. Consultar fuentes independientes o especialistas que hayan señalado la relevancia del tema omitido."
    ]
  }
}
